cat > /home/eval/recon/reconcile.awk <<'EOF'
# Reconcile ledger.csv (RFC 4180 CSV) with bank.tsv (tab-separated).
# All amounts converted to integer cents -> exact arithmetic, no floats.

function parse_csv_line(s, arr,   i,n,c,f,nf,inq) {
    nf=0; f=""; inq=0; n=length(s)
    for (i=1;i<=n;i++) {
        c=substr(s,i,1)
        if (inq) {
            if (c=="\"") {
                if (i<n && substr(s,i+1,1)=="\"") { f=f "\""; i++ }
                else inq=0
            } else f=f c
        } else {
            if (c=="\"") inq=1
            else if (c==",") { arr[++nf]=f; f="" }
            else f=f c
        }
    }
    arr[++nf]=f
    return nf
}

function to_cents(s,   neg,intp,frac) {
    gsub(/[ \t]/,"",s)          # safety: strip stray whitespace
    neg = (s ~ /^-/) ? -1 : 1
    sub(/^[-+]/,"",s)
    if (s !~ /\./) s = s "."
    intp = s; sub(/\..*/,"",intp)
    frac = s; sub(/^[^.]*\./,"",frac)
    if (intp=="") intp="0"
    frac = (frac "00")
    return neg * (intp*100 + substr(frac,1,2) + 0)
}

function dmy_to_iso(d,   p) {
    split(d,p,"/")
    return sprintf("%04d-%02d-%02d", p[3], p[2], p[1])
}

function fmt(c,   ip,fp) {
    ip = int(c/100); fp = c - ip*100
    return sprintf("%d.%02d", ip, fp)
}

# ---- pass 1: ledger.csv ----
NR==FNR {
    if (FNR==1) next            # header
    n = parse_csv_line($0, F)
    id  = F[1]
    Ldate[id] = F[2]
    amt = F[4]; gsub(/,/,"",amt)   # strip thousands separators
    Lamt[id] = to_cents(amt)
    Lseen[id] = 1
    ltotal += Lamt[id]
    lrows++
    next
}

# ---- pass 2: bank.tsv ----
FNR==1 { next }                 # header
{
    ref = $1
    gsub(/^[ \t]+|[ \t]+$/,"",ref)
    ref = toupper(ref)
    d   = dmy_to_iso($2)
    a   = to_cents($4)
    key = ref SUBSEP d SUBSEP a
    if (key in dupchk) { dups++; next }
    dupchk[key] = 1
    Bdate[ref] = d
    Bamt[ref]  = a
    Bseen[ref] = 1
    btotal += a
    brows++
}

END {
    for (id in Lseen) ids[id]=1
    for (id in Bseen) ids[id]=1
    nid=0
    for (id in ids) sorted[++nid]=id
    n = asort(sorted)

    matched=0; n_amt=0; n_date=0; n_mib=0; n_mil=0
    for (i=1;i<=n;i++) {
        id = sorted[i]
        if ((id in Lseen) && (id in Bseen)) {
            ea = (Lamt[id]==Bamt[id])
            ed = (Ldate[id]==Bdate[id])
            if (ea && ed) {
                matched++
            } else {
                if (!ea) { n_amt++;  amt_det[n_amt]  = "  " id " ledger=" fmt(Lamt[id]) " bank=" fmt(Bamt[id]) }
                if (!ed) { n_date++; date_det[n_date]= "  " id " ledger=" Ldate[id] " bank=" Bdate[id] }
            }
        } else if (id in Lseen) {
            n_mib++; mib_det[n_mib] = "  " id
        } else {
            n_mil++; mil_det[n_mil] = "  " id
        }
    }

    print "ledger_rows: " lrows
    print "bank_rows: " brows
    print "duplicate_bank_rows: " (dups+0)
    print "ledger_total: " fmt(ltotal)
    print "bank_total: " fmt(btotal)
    print "matched: " matched
    print "amount_mismatch: " n_amt
    for (i=1;i<=n_amt;i++)  print amt_det[i]
    print "date_mismatch: " n_date
    for (i=1;i<=n_date;i++) print date_det[i]
    print "missing_in_bank: " n_mib
    for (i=1;i<=n_mib;i++)  print mib_det[i]
    print "missing_in_ledger: " n_mil
    for (i=1;i<=n_mil;i++)  print mil_det[i]
}
EOF
mkdir -p /home/eval/recon/out
awk -f /home/eval/recon/reconcile.awk /home/eval/recon/ledger.csv /home/eval/recon/bank.tsv > /home/eval/recon/out/reconciliation.txt
echo "exit: $?"
cat /home/eval/recon/out/reconciliation.txt

